      >
        {/* Header */}
        <div
          className="sticky top-0 flex items-center justify-between p-6"
          style={{
            backgroundColor: '#1a1a1a',
            borderBottom: '1px solid rgba(255, 255, 255, 0.06)'
          }}
        >
          <div>
            <h2
              style={{
                color: '#d0d0d0',
                fontFamily: 'var(--font-display)',
                fontSize: '18px',
                fontWeight: 500,
                letterSpacing: '0.04em',
                marginBottom: '4px'
              }}
            >
              Tools & Downloads
            </h2>
            <p
              style={{
                color: '#5a5a5a',
                fontFamily: 'var(--font-open-sans)',
                fontSize: '13px'
              }}
            >
              You found the secret stash
            </p>
          </div>

          {/* Close button */}
          <button
            onClick={onClose}
            className="transition-opacity hover:opacity-60"
            style={{
              padding: '8px',
              marginRight: '-8px'
            }}
            aria-label="Close"
          >
            <svg
              width="20"
              height="20"
              viewBox="0 0 24 24"
              fill="none"
              stroke="#7a7a7a"
              strokeWidth="1.5"
              strokeLinecap="round"
            >
              <line x1="18" y1="6" x2="6" y2="18" />
              <line x1="6" y1="6" x2="18" y2="18" />
            </svg>
          </button>
        </div>

        {/* Tools list */}
        <div className="p-6 space-y-6">
          {downloadableTools.map((tool) => (
            <div
