export default function OGVFXFramePage() {
  return (
    <div style={{ padding: '100px', color: '#a0a0a0', backgroundColor: '#141414', minHeight: '100vh' }}>
      <h1 style={{ fontFamily: 'var(--font-lora)', fontStyle: 'italic', fontSize: '32px', marginBottom: '24px' }}>
        OG Image Preview - Option 2: VFX Frame
      </h1>
      <p style={{ fontFamily: 'var(--font-open-sans)', fontSize: '16px', marginBottom: '16px' }}>
        View the generated image at: <code>/og-vfx-frame/opengraph-image</code>
      </p>
      <p style={{ fontFamily: 'var(--font-open-sans)', fontSize: '14px', color: '#6a6a6a' }}>
        Option 1 (Portrait): <code>/opengraph-image</code>
      </p>
    </div>
  );
}

