'use client';

import { useState, useMemo, useEffect, useRef } from 'react';
import { ProjectCard } from './ProjectCard';
import { ProjectAdapter } from '@/lib/perception/adapter';
import { VisitorArchetype } from '@/lib/perception/types';
import type { Project } from '@/lib/projects';
import type { PerceptionState } from '@/lib/perception/types';

interface ProjectGridProps {
  projects: Project[];
  allDisciplines: string[];
  perceptionState?: PerceptionState | null;
}

export function ProjectGrid({ projects, allDisciplines, perceptionState }: ProjectGridProps) {
  const [activeDiscipline, setActiveDiscipline] = useState<string | null>(null);

  // State to hold the displayed project order (frozen during browsing)
  const [displayedProjects, setDisplayedProjects] = useState<Project[]>(projects);

  // Track whether we've applied adaptation this session
  const hasAppliedAdaptation = useRef(false);

  /**
   * INVISIBLE SHUFFLE STRATEGY:
   * - Perception learns silently while user browses
   * - Projects remain in same order (no live reordering)
   * - When component mounts (user returns from project page), apply the adaptation
   * - User experiences: "The grid shuffled while I was away!"
   */
  useEffect(() => {
    // Only apply adaptation once per component mount
    if (
      !hasAppliedAdaptation.current &&
      perceptionState &&
      perceptionState.profile.archetype !== VisitorArchetype.UNKNOWN
    ) {
      const adapted = ProjectAdapter.adaptProjectOrder(projects, perceptionState.profile.archetype);
      setDisplayedProjects(adapted);
      hasAppliedAdaptation.current = true;
    }
  }, [perceptionState, projects]);

  // Filter projects based on active discipline (single-select)
  const filteredProjects = useMemo(() => {
    if (!activeDiscipline) return displayedProjects;

    return displayedProjects.filter(project => {
      return project.disciplines.includes(activeDiscipline);
    });
  }, [displayedProjects, activeDiscipline]);

  const handleDisciplineClick = (discipline: string) => {
    // Toggle: click same discipline to deselect
    setActiveDiscipline(prev => prev === discipline ? null : discipline);
  };

  const clearFilters = () => {
    setActiveDiscipline(null);
  };

  return (
    <div className="space-y-8">
      {/* Filter bar temporarily hidden */}
      {false && (
        <div className="pb-6">
          <div className="flex flex-col md:flex-row md:items-start md:justify-between gap-4">
            {/* Discipline filters - Two rows */}
            <div>
              <div className="flex flex-col gap-3">
                {/* First row: EVERYTHING, LIGHTING, COMMISSIONS */}
                <div className="flex flex-wrap gap-4 md:gap-6">
                  {allDisciplines.slice(0, 3).map(discipline => (
                    <button
                      key={discipline}
                      onClick={() => handleDisciplineClick(discipline)}
                      className="text-xs md:text-sm transition-all duration-200"
                      style={{
                        color: activeDiscipline === discipline ? '#000000' : '#6a6a6a',
                        fontFamily: 'var(--font-lora)',
                        fontWeight: activeDiscipline === discipline ? 700 : 600,
                        letterSpacing: '0.06em'
                      }}
                    >
                      {discipline}
                    </button>
                  ))}
                </div>
                {/* Second row: DIRECTION, EXPERIMENTAL, R&D */}
                <div className="flex flex-wrap gap-4 md:gap-6">
                  {allDisciplines.slice(3).map(discipline => (
                    <button
                      key={discipline}
                      onClick={() => handleDisciplineClick(discipline)}
                      className="text-xs md:text-sm transition-all duration-200"
                      style={{
                        color: activeDiscipline === discipline ? '#000000' : '#6a6a6a',
                        fontFamily: 'var(--font-lora)',
                        fontWeight: activeDiscipline === discipline ? 700 : 600,
                        letterSpacing: '0.06em'
                      }}
                    >
                      {discipline}
                    </button>
                  ))}
                </div>
              </div>
            </div>

            {/* Clear filters */}
            {activeDiscipline && (
              <button
                onClick={clearFilters}
                className="text-sm text-neutral-500 hover:text-black transition-colors whitespace-nowrap md:ml-auto"
              >
                clear ×
              </button>
            )}
          </div>

          {/* Active filter count */}
          {activeDiscipline && (
            <p className="text-sm text-neutral-500 mt-4">
              {filteredProjects.length} {filteredProjects.length === 1 ? 'project' : 'projects'} found
            </p>
          )}
        </div>
      )}

      {/* Grid Pattern: 1 hero → all remaining in 2-column grid */}
      <div className="space-y-12">
        {filteredProjects.map((project, index) => {
          // Only first project is hero, all others are grid items
          const isHero = index === 0;

          if (isHero) {
            // Full-width hero (first project only)
            return (
              <ProjectCard
                key={project.id}
                project={project}
              />
            );
          }

          if (index === 1) {
            // Start of grid - collect all remaining projects
            const gridProjects = filteredProjects.slice(1);
            return (
              <div key="grid-all" className="grid grid-cols-1 md:grid-cols-2 gap-6 md:gap-8">
                {gridProjects.map(gridProject => (
                  <ProjectCard
                    key={gridProject.id}
                    project={gridProject}
                  />
                ))}
              </div>
            );
          }

          // Skip - already rendered as part of grid
          return null;
        })}
      </div>

      {/* No results */}
      {filteredProjects.length === 0 && (
        <div className="text-center py-16">
          <p className="text-neutral-500">No projects found with selected filters.</p>
          <button
            onClick={clearFilters}
            className="mt-4 text-sm text-black hover:opacity-70 transition-opacity"
          >
            Clear filters
          </button>
        </div>
      )}
    </div>
  );
}

'use client';

import { useEffect, useState } from 'react';

type CursorState = 'default' | 'link' | 'video' | 'button';

export function CustomCursor() {
  const [position, setPosition] = useState({ x: -100, y: -100 });
  const [cursorState, setCursorState] = useState<CursorState>('default');
  const [isVisible, setIsVisible] = useState(false);
  const [animationKey, setAnimationKey] = useState(0);
  const [isOverMetatag, setIsOverMetatag] = useState(false);
  const [currentVideoSlug, setCurrentVideoSlug] = useState<string | null>(null);
  const [isPressed, setIsPressed] = useState(false);

  useEffect(() => {
    // Check if device supports hover (desktop only)
    const hasHover = window.matchMedia('(hover: hover) and (pointer: fine)').matches;
    if (!hasHover) return;

    setIsVisible(true);

    const updateCursor = (e: MouseEvent) => {
      setPosition({ x: e.clientX, y: e.clientY });

      // Always use normal browser cursor
      setIsOverMetatag(true);
      setCursorState('default');
      setCurrentVideoSlug(null);
    };

    window.addEventListener('mousemove', updateCursor);

    return () => {
      window.removeEventListener('mousemove', updateCursor);
    };
  }, [cursorState]);

  // Trigger animation when entering video hover state, and repeat continuously every 3 seconds
  // Watch currentVideoSlug so animation retriggers when moving between different videos
  useEffect(() => {
    let animationInterval: NodeJS.Timeout | null = null;

    if (cursorState === 'video' && currentVideoSlug) {
      // Trigger initial animation immediately on EVERY video entry (including switching between videos)
      setAnimationKey(prev => prev + 1);

      // Set interval to continuously repeat animation every 3 seconds while hovering
      animationInterval = setInterval(() => {
        setAnimationKey(prev => prev + 1);
      }, 3000);
    }

    // Cleanup interval if user leaves video hover
    return () => {
      if (animationInterval) {
        clearInterval(animationInterval);
      }
    };
  }, [cursorState, currentVideoSlug]);

  if (!isVisible) return null;

  // Cursor properties based on state
  const getCursorProps = () => {
    switch (cursorState) {
      case 'video':
        return {
          width: 'auto',
          height: 'auto',
          padding: '0.25rem 0.625rem', // Match metatag padding (py-1 px-2.5)
          color: '#181818', // Dark grey background (matches site)
          text: 'play',
          fontSize: '11px',
          fontWeight: 600, // Semibold weight
          letterSpacing: '0.04em', // Subtle letter spacing
          textColor: '#f5f5f5', // Project title color
          fontFamily: 'var(--font-display)', // Match site font
          borderRadius: '6px' // Match metatag rounded-md
        };
      case 'link':
        return {
          width: 20,
          height: 20,
          padding: '0',
          color: '#6a6a6a',
          text: '.',
          fontSize: '20px',
          fontWeight: 400,
          letterSpacing: '0',
          textColor: '#d9d9d9',
          fontFamily: 'var(--font-dm-sans), -apple-system, BlinkMacSystemFont, sans-serif',
          borderRadius: '2px'
        };
      case 'button':
        return {
          width: 20,
          height: 20,
          padding: '0',
          color: '#4a4a4a',
          text: '.',
          fontSize: '20px',
          fontWeight: 400,
          letterSpacing: '0',
          textColor: '#d9d9d9',
          fontFamily: 'var(--font-dm-sans), -apple-system, BlinkMacSystemFont, sans-serif',
          borderRadius: '2px'
        };
      default:
        return {
          width: 20,
          height: 20,
          padding: '0',
          color: '#8a8a8a',
          text: '.',
          fontSize: '20px',
          fontWeight: 400,
          letterSpacing: '0',
          textColor: '#d9d9d9',
          fontFamily: 'var(--font-dm-sans), -apple-system, BlinkMacSystemFont, sans-serif',
          borderRadius: '2px'
        };
    }
  };

  const { width, height, padding, color, text, fontSize, fontWeight, letterSpacing, textColor, fontFamily, borderRadius } = getCursorProps();

  // Lighten colors when pressed (dark background needs to brighten)
  const activeBackgroundColor = isPressed && cursorState === 'video' ? '#303030' : color;
  const activeTextColor = isPressed && cursorState === 'video' ? '#ffffff' : textColor;

  return (
    <>

      {/* Filled pill cursor with text */}
      <div
        style={{
          position: 'fixed',
          left: 0,
          top: 0,
          width: typeof width === 'number' ? `${width}px` : width,
          height: typeof height === 'number' ? `${height}px` : height,
          padding: padding,
          backgroundColor: activeBackgroundColor,
          opacity: isOverMetatag ? 0 : 1,
          pointerEvents: 'none',
          transform: `translate(${position.x}px, ${position.y}px) translate(-50%, -50%)`,
          transition: 'width 0.3s cubic-bezier(0.16, 1, 0.3, 1), height 0.3s cubic-bezier(0.16, 1, 0.3, 1), background-color 0.1s ease-out, transform 0.04s ease-out, opacity 0.2s ease-out',
          zIndex: 9999,
          willChange: 'transform, width, height, background-color',
          borderRadius: borderRadius,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          color: activeTextColor,
          fontFamily: fontFamily,
          fontSize: fontSize,
          fontWeight: fontWeight,
          letterSpacing: letterSpacing,
          textTransform: cursorState === 'video' ? 'uppercase' : 'none',
          userSelect: 'none',
          overflow: 'hidden',
          perspective: '200px'
        }}
      >
        <span
          key={animationKey}
          style={{
            opacity: 1,
            lineHeight: 1,
            animation: cursorState === 'video' ? 'filmReelRotate 0.8s cubic-bezier(0.45, 0, 0.55, 1) forwards' : 'none',
            transformStyle: 'preserve-3d'
          }}
        >
          {text}
        </span>
      </div>
    </>
  );
}

