                        letterSpacing: '0.01em'
                      }}
                    >
                      {message.text}
                    </h2>
                  ) : (
                    <>
                      {/* Speaker label */}
                      <span
                        style={{
                          display: 'block',
                          color: '#5a5a5a',
                          fontFamily: 'var(--font-display)',
                          fontWeight: 600,
                          fontSize: '10px',
                          letterSpacing: '0.18em',
                          textTransform: 'uppercase',
                          marginBottom: '14px'
                        }}
                      >
                        {message.type === 'user' ? 'You' : 'Joseph Ibrahim'}
                      </span>
                      {/* Message text with rich content */}
                      <div
                        style={{
                          color: message.type === 'user' ? '#7a7a7a' : '#9a9a9a',
                          fontFamily: 'var(--font-display)',
                          fontWeight: 400,
