            <span
              style={{
                color: '#a0a0a0',
                fontFamily: 'var(--font-lora)',
                fontStyle: 'italic',
                fontSize: '15px'
              }}
              className="group-hover:text-white transition-colors"
            >
              {relatedProject.title}
            </span>
            <svg
              width="14"
              height="14"
              viewBox="0 0 16 16"
              fill="none"
              stroke="currentColor"
              strokeWidth="1.5"
              style={{ color: '#5a5a5a', transition: 'transform 200ms ease' }}
              className="group-hover:translate-x-1"
            >
              <path d="M6 4L10 8L6 12" />
            </svg>
          </Link>
        )}

        {/* Breakdown Video */}
        {vimeoEmbedUrl && (
          <div className="mb-8 sm:mb-12">
            <p
              style={{
                color: '#5a5a5a',
                fontFamily: 'var(--font-display)',
                fontSize: '11px',
                fontWeight: 600,
                letterSpacing: '0.15em',
                textTransform: 'uppercase',
                marginBottom: '16px'
              }}
            >
              Breakdown
            </p>
            <div
              style={{
                position: 'relative',
                paddingBottom: '56.25%', // 16:9
                height: 0,
                overflow: 'hidden',
                borderRadius: '6px',
                backgroundColor: '#0a0a0a'
              }}
            >
              <iframe
                src={vimeoEmbedUrl}
                style={{
                  position: 'absolute',
                  top: 0,
                  left: 0,
                  width: '100%',
                  height: '100%',
                  border: 0
                }}
                allow="autoplay; fullscreen; picture-in-picture"
                allowFullScreen
                title="Breakdown video"
              />
            </div>
          </div>
        )}

        {/* Content */}
        <div className="mb-8 sm:mb-12">
          {contentSections}
