'use client';

import Link from 'next/link';
import { VideoThumbnail } from './VideoThumbnail';
import type { Project } from '@/lib/projects';

/**
 * TENDRIL-STYLE PROJECT CARD
 *
 * Design philosophy:
 * - Titles always visible below thumbnail (scan-friendly)
 * - Video plays on hover (motion draws attention)
 * - Clean typography hierarchy: title → description → client
 * - Description first: leads with thinking, not credits
 * - Client as footnote: credibility signal, not headline
 * - No category tags - let the visuals speak
 */

interface ProjectCardProps {
  project: Project;
  isHero?: boolean;
}

export function ProjectCard({ project }: ProjectCardProps) {
  const aspectRatio = '16/9';

  return (
    <article
      className="group relative w-full project-card"
      data-project-slug={project.slug}
    >
      {/* Video Thumbnail Container - Clean, no overlays */}
      <Link
        href={`/projects/${project.slug}`}
        className="block relative w-full overflow-hidden project-thumbnail"
        data-project-slug={project.slug}
        style={{ borderRadius: 'var(--radius-md)' }}
      >
        <VideoThumbnail
          videoId={project.videoId}
          videoHash={project.videoHash}
          aspectRatio={aspectRatio}
          startTime={project.startTime}
          isCinematic={project.isCinematic}
          thumbnail={project.thumbnail}
        />
      </Link>

      {/* Title + Client - Always visible below thumbnail */}
      <Link
        href={`/projects/${project.slug}`}
        className="block group-hover:opacity-60"
        style={{
          paddingTop: 'var(--space-xs)',
          transition: 'opacity var(--transition-base)'
        }}
      >
        <h3
          style={{
            color: 'var(--text-primary)',
            fontWeight: 400,
            fontFamily: 'var(--font-lora)',
            fontStyle: 'italic',
            letterSpacing: '0.01em',
            fontSize: 'clamp(22px, 2.2vw, 28px)',
            lineHeight: 1.25,
            marginBottom: project.gridDescription || project.client ? 'var(--space-tiny)' : 0
          }}
        >
          {project.title}
        </h3>

        {/* Description - readable but clearly secondary to title */}
        {project.gridDescription ? (
          <p
            style={{
              color: 'var(--grey-500)',
              fontFamily: 'var(--font-open-sans)',
              fontWeight: 400,
              fontSize: '17px',
              lineHeight: 1.95,
              marginBottom: project.client ? 'var(--space-tiny)' : 0
            }}
          >
            {project.gridDescription}
          </p>
        ) : null}

        {/* Client as footnote - dimmest, true metadata */}
        {project.client ? (
          <p
            style={{
              color: 'var(--text-dim)',
              fontFamily: 'var(--font-display)',
              fontWeight: 500,
              fontSize: '11px',
              letterSpacing: '0.12em',
              textTransform: 'uppercase'
            }}
          >
            {project.client}
          </p>
        ) : null}
      </Link>
    </article>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { LadderGrid } from '@/components/LadderGrid';
import { genAiProjects } from '@/lib/gen-ai-projects';

/**
 * Gen AI Portfolio Page
 *
 * Showcases generative AI and cognitive systems work.
 * Publicly accessible - no longer gated behind awareness mode.
 */
export default function GenAiPage() {
  const [introVisible, setIntroVisible] = useState(false);
  const [prefersReducedMotion, setPrefersReducedMotion] = useState(false);
  const [isMobile, setIsMobile] = useState(false);

  // Detect mobile and reduced motion preference
  useEffect(() => {
    const checkMobile = () => {
      const isTouchDevice = 'ontouchstart' in window || navigator.maxTouchPoints > 0;
      const isNarrowViewport = window.innerWidth < 768;
      setIsMobile(isTouchDevice || isNarrowViewport);
    };
    checkMobile();
    window.addEventListener('resize', checkMobile);

    const motionQuery = window.matchMedia('(prefers-reduced-motion: reduce)');
    setPrefersReducedMotion(motionQuery.matches);
    const handleMotionChange = (e: MediaQueryListEvent) => setPrefersReducedMotion(e.matches);
    motionQuery.addEventListener('change', handleMotionChange);

    return () => {
      window.removeEventListener('resize', checkMobile);
      motionQuery.removeEventListener('change', handleMotionChange);
    };
  }, []);

  // Trigger intro animation on mount
  useEffect(() => {
    const timer = setTimeout(() => setIntroVisible(true), 100);
    return () => clearTimeout(timer);
  }, []);

  return (
    <main className="min-h-screen relative" style={{ paddingTop: '120px', zIndex: 50, backgroundColor: '#141414' }}>
      {/* Hero Statement - Gen AI specific */}
      <section
        className="mx-auto"
        style={{
          maxWidth: 'var(--max-content-width)',
          paddingLeft: 'var(--side-padding)',
          paddingRight: 'var(--side-padding)',
          paddingTop: 'clamp(60px, 6vw + 20px, 100px)',
          paddingBottom: 'clamp(80px, 8vw + 27px, 140px)',
        }}
      >
        <div style={{ maxWidth: '900px' }}>
          {/* Hero Statement */}
          <h1
            style={{
              color: '#a0a0a0',
              fontFamily: 'var(--font-lora)',
              fontWeight: 400,
              fontStyle: 'italic',
              fontSize: 'clamp(22px, 3.5vw, 38px)',
              lineHeight: 1.3,
              letterSpacing: '0.01em',
              opacity: introVisible ? 1 : 0,
              transform: introVisible ? 'translateY(0)' : `translateY(${isMobile ? 20 : 30}px)`,
              transition: prefersReducedMotion ? 'none' : 'opacity 550ms cubic-bezier(0.25, 0.1, 0.25, 1) 100ms, transform 550ms cubic-bezier(0.25, 0.1, 0.25, 1) 100ms'
            }}
          >
            Where sixteen years of lighting craft meets generative systems. These projects explore how AI can serve creative practice — not replace it.
          </h1>

          {/* Subtext */}
          <p
            style={{
              color: '#666',
              fontFamily: 'var(--font-display)',
              fontWeight: 400,
              fontSize: 'clamp(14px, 1vw + 10px, 16px)',
              lineHeight: 1.6,
              marginTop: '32px',
              maxWidth: '700px',
              opacity: introVisible ? 1 : 0,
              transform: introVisible ? 'translateY(0)' : 'translateY(20px)',
              transition: prefersReducedMotion ? 'none' : 'opacity 550ms ease 200ms, transform 550ms ease 200ms'
            }}
          >
            The same generative thinking that shapes your experience here powers these projects.
          </p>
        </div>
      </section>

      {/* Project Grid */}
      <section
        className="mx-auto"
        style={{
          maxWidth: 'var(--max-content-width)',
          paddingLeft: 'var(--side-padding)',
          paddingRight: 'var(--side-padding)',
          paddingBottom: 'var(--space-lg)'
        }}
      >
        <LadderGrid projects={genAiProjects} />
      </section>
    </main>
  );
}

'use client';

import { useState, useEffect } from 'react';
import {
  getProcessPostsByCategory,
  categoryLabels,
  type ProcessCategory
} from '@/lib/process-posts';
import AccordionCategory from '@/components/AccordionCategory';
import ProcessThumbnail from '@/components/ProcessThumbnail';

/**
 * PROCESS Page - Accordion-Style Category Reveal
 *
 * Four categories with hover/tap to expand:
 * - Case Studies: Project deep dives
 * - Tools: Downloadable tools
 * - Research: Blog-style methodology posts
 * - Experiments: Visual scenes/prototypes
 *
 * Desktop: Hover to expand (150ms delay, sticky)
 * Mobile: Tap to toggle
 */

const CATEGORY_ORDER: ProcessCategory[] = [
  'case-studies',
  'tools',
  'research',
  'experiments'
];

export default function ProcessPage() {
  const [introVisible, setIntroVisible] = useState(false);
  const [prefersReducedMotion, setPrefersReducedMotion] = useState(false);
  // Default to CASE STUDIES open on page load
  const [expandedCategory, setExpandedCategory] = useState<ProcessCategory | null>('case-studies');

  // Detect reduced motion preference
  useEffect(() => {
    const motionQuery = window.matchMedia('(prefers-reduced-motion: reduce)');
    setPrefersReducedMotion(motionQuery.matches);
    const handleMotionChange = (e: MediaQueryListEvent) => setPrefersReducedMotion(e.matches);
    motionQuery.addEventListener('change', handleMotionChange);
    return () => motionQuery.removeEventListener('change', handleMotionChange);
  }, []);

  // Trigger intro animation on mount
  useEffect(() => {
    const timer = setTimeout(() => setIntroVisible(true), 100);
    return () => clearTimeout(timer);
  }, []);

  // Get posts for each category
  const categoryPosts = CATEGORY_ORDER.map(cat => ({
    category: cat,
    posts: getProcessPostsByCategory(cat)
  }));

  // Handle toggle - cascading behavior: closing one opens the next
  const handleToggle = (category: ProcessCategory) => {
    setExpandedCategory(prev => {
      if (prev === category) {
        // Closing current category - cascade to next
        const currentIndex = CATEGORY_ORDER.indexOf(category);
        const nextIndex = currentIndex + 1;
        // If there's a next category, open it; otherwise close all
        return nextIndex < CATEGORY_ORDER.length ? CATEGORY_ORDER[nextIndex] : null;
      } else {
        // Opening a different category
        return category;
      }
    });
  };

  return (
    <div className="min-h-screen" style={{ backgroundColor: '#141414' }}>
      <main
        className="mx-auto pb-32"
        style={{
          maxWidth: 'var(--max-content-width)',
          paddingTop: 'clamp(100px, 8vw + 60px, 180px)',
          paddingLeft: 'var(--side-padding)',
          paddingRight: 'var(--side-padding)'
        }}
      >
        {/* Hero Statement */}
        {/* Mobile: 48px margin, Desktop: 76px */}
        <section className="mb-12 sm:mb-[76px]">
          <h1
            style={{
              color: '#a0a0a0',
              fontFamily: 'var(--font-lora)',
              fontWeight: 400,
              fontStyle: 'italic',
              fontSize: 'clamp(22px, 3.5vw, 38px)',
              lineHeight: 1.3,
              letterSpacing: '0.01em',
              maxWidth: '900px',
              opacity: introVisible ? 1 : 0,
              transform: introVisible ? 'translateY(0)' : 'translateY(30px)',
              transition: prefersReducedMotion ? 'none' : 'opacity 550ms cubic-bezier(0.25, 0.1, 0.25, 1) 100ms, transform 550ms cubic-bezier(0.25, 0.1, 0.25, 1) 100ms'
            }}
          >
            Behind the final frame: tools built, problems solved, and the thinking that shapes the work.
          </h1>
        </section>

        {/* Accordion Categories */}
        <div
          style={{
            opacity: introVisible ? 1 : 0,
            transform: introVisible ? 'translateY(0)' : 'translateY(20px)',
            transition: prefersReducedMotion ? 'none' : 'opacity 550ms ease 200ms, transform 550ms ease 200ms'
          }}
        >
          {categoryPosts.map(({ category, posts }) => (
            <AccordionCategory
              key={category}
              title={categoryLabels[category]}
              count={posts.length}
              isExpanded={expandedCategory === category}
              onToggle={() => handleToggle(category)}
              prefersReducedMotion={prefersReducedMotion}
            >
              {/* Item List - vertical stack like INFO page */}
              {/* Mobile: 24px gap, Desktop: 32px gap */}
              {/* Pentagram-style generous vertical rhythm */}
              <div className="flex flex-col gap-8 sm:gap-12">
                {posts.map((post) => (
                  <ProcessThumbnail
                    key={post.id}
                    slug={post.slug}
                    title={post.title}
                    excerpt={post.excerpt}
                    version={post.version}
                    thumbnail={post.thumbnail}
                    githubUrl={post.githubUrl}
                  />
                ))}
              </div>

              {/* Empty state */}
              {posts.length === 0 && (
                <p
                  style={{
                    color: '#5a5a5a',
                    fontFamily: 'var(--font-display)',
                    fontSize: '14px',
                    fontStyle: 'italic'
                  }}
                >
                  Coming soon.
                </p>
              )}
            </AccordionCategory>
          ))}
        </div>
      </main>
    </div>
  );
}

