'use client';

import { useState } from 'react';
import Link from 'next/link';

/**
 * ProcessThumbnail - Clean item card for PROCESS page
 *
 * COLOR HIERARCHY MANTRA:
 * - Title: --text-primary (brightest)
 * - Description: --grey-500 (medium)
 * - Version: --text-dim (dimmest)
 *
 * Information hierarchy = Color hierarchy
 */

interface ProcessThumbnailProps {
  slug: string;
  title: string;
  excerpt: string;
  version?: string;
  thumbnail?: string;
  githubUrl?: string;
}

export default function ProcessThumbnail({
  slug,
  title,
  excerpt,
  version,
  thumbnail,
  githubUrl
}: ProcessThumbnailProps) {
  const [isHovered, setIsHovered] = useState(false);

  // If there's a GitHub URL, link to that; otherwise link to internal page
  const linkProps = githubUrl
    ? { href: githubUrl, target: '_blank', rel: 'noopener noreferrer' as const }
    : { href: `/process/${slug}` };

  const Wrapper = githubUrl ? 'a' : Link;

  return (
    <Wrapper
      {...linkProps}
      className="flex flex-col sm:flex-row gap-4 sm:gap-6 group"
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
    >
      {/* Thumbnail - real image or placeholder */}
      {/* Mobile: full width capped at 390px, Desktop: 240px (125% of previous) */}
      <div
        className="flex-shrink-0 w-full max-w-[390px] sm:w-[240px] sm:max-w-none"
        style={{
          aspectRatio: '16 / 9',
          borderRadius: '4px',
          overflow: 'hidden',
          backgroundColor: thumbnail ? 'transparent' : 'rgba(255, 255, 255, 0.04)',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center'
        }}
      >
        {thumbnail ? (
          <img
            src={thumbnail}
            alt={title}
            style={{
              width: '100%',
              height: '100%',
              objectFit: 'cover',
              opacity: isHovered ? 0.8 : 1,
              transition: 'opacity 200ms ease'
            }}
          />
        ) : (
          /* Placeholder X */
          <svg
            width="24"
            height="24"
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            strokeWidth="1.5"
            strokeLinecap="round"
            style={{
              color: isHovered ? 'rgba(255, 255, 255, 0.25)' : 'rgba(255, 255, 255, 0.15)',
              transition: 'color 200ms ease'
            }}
          >
            <path d="M6 6L18 18M6 18L18 6" />
          </svg>
        )}
      </div>

      {/* Content */}
      <div className="flex flex-col justify-center min-w-0">
        {/* Title - PRIMARY in hierarchy */}
        <h3
          className="text-[13px] sm:text-[17px] md:text-[clamp(17px,1.7vw,20px)] flex items-center gap-2"
          style={{
            color: isHovered ? 'var(--grey-50)' : 'var(--text-primary)',
            fontFamily: 'var(--font-display)',
            fontWeight: 500,
            lineHeight: 1.25,
            letterSpacing: '0.02em',
            marginBottom: '8px',
            transition: 'color 200ms ease'
          }}
        >
          {title}
          {/* GitHub indicator - TERTIARY */}
          {githubUrl && (
            <svg
              width="16"
              height="16"
              viewBox="0 0 24 24"
              fill="currentColor"
              style={{
                color: isHovered ? 'var(--grey-500)' : 'var(--text-dim)',
                transition: 'color 200ms ease',
                flexShrink: 0
              }}
              aria-label="Available on GitHub"
            >
              <path d="M12 0c-6.626 0-12 5.373-12 12 0 5.302 3.438 9.8 8.207 11.387.599.111.793-.261.793-.577v-2.234c-3.338.726-4.033-1.416-4.033-1.416-.546-1.387-1.333-1.756-1.333-1.756-1.089-.745.083-.729.083-.729 1.205.084 1.839 1.237 1.839 1.237 1.07 1.834 2.807 1.304 3.492.997.107-.775.418-1.305.762-1.604-2.665-.305-5.467-1.334-5.467-5.931 0-1.311.469-2.381 1.236-3.221-.124-.303-.535-1.524.117-3.176 0 0 1.008-.322 3.301 1.23.957-.266 1.983-.399 3.003-.404 1.02.005 2.047.138 3.006.404 2.291-1.552 3.297-1.23 3.297-1.23.653 1.653.242 2.874.118 3.176.77.84 1.235 1.911 1.235 3.221 0 4.609-2.807 5.624-5.479 5.921.43.372.823 1.102.823 2.222v3.293c0 .319.192.694.801.576 4.765-1.589 8.199-6.086 8.199-11.386 0-6.627-5.373-12-12-12z"/>
            </svg>
          )}
        </h3>

        {/* Description - SECONDARY in hierarchy */}
        <p
          className="text-[13px] sm:text-[18px]"
          style={{
            color: 'var(--grey-500)',
            fontFamily: 'var(--font-display)',
            fontWeight: 300,
            lineHeight: 1.6,
            letterSpacing: '-0.01em',
            display: '-webkit-box',
            WebkitLineClamp: 2,
            WebkitBoxOrient: 'vertical',
            overflow: 'hidden'
          }}
        >
          {excerpt}
        </p>

        {/* Version - TERTIARY in hierarchy */}
        {version && (
          <span
            style={{
              color: 'var(--text-dim)',
              fontFamily: 'var(--font-display)',
              fontSize: '12px',
              fontWeight: 500,
              letterSpacing: '0.08em',
              textTransform: 'uppercase',
              marginTop: '12px'
            }}
          >
            v{version}
          </span>
        )}
      </div>
    </Wrapper>
  );
}

import { notFound } from 'next/navigation';
import Link from 'next/link';
import { getProcessPost, processPosts } from '@/lib/process-posts';
import { getProject } from '@/lib/projects';

/**
 * Process Post Detail Page
 *
 * Renders full content for case studies, tools, research, experiments.
 * Includes breakdown video embed for case studies.
 * Links back to related project when projectSlug is set.
 */

// Generate static paths for all process posts
export async function generateStaticParams() {
  return processPosts.map((post) => ({
    slug: post.slug,
  }));
}

// Generate metadata
export async function generateMetadata({ params }: { params: Promise<{ slug: string }> }) {
  const { slug } = await params;
  const post = getProcessPost(slug);

  if (!post) {
    return { title: 'Not Found' };
  }

  return {
    title: `${post.title} | Process`,
    description: post.excerpt,
    openGraph: {
      title: post.title,
      description: post.excerpt,
      url: `https://josephibrahim.com/process/${slug}`,
      type: 'article',
    },
    twitter: {
      card: 'summary_large_image',
      title: post.title,
      description: post.excerpt,
    },
    alternates: {
      canonical: `https://josephibrahim.com/process/${slug}`,
    },
  };
}

export default async function ProcessPostPage({ params }: { params: Promise<{ slug: string }> }) {
  const { slug } = await params;
  const post = getProcessPost(slug);

  if (!post) {
    notFound();
  }

  // Get related project if exists
  const relatedProject = post.projectSlug ? getProject(post.projectSlug) : null;

  // Build Vimeo embed URL
  const vimeoEmbedUrl = post.breakdownVideoId
    ? `https://player.vimeo.com/video/${post.breakdownVideoId}${post.breakdownVideoHash ? `?h=${post.breakdownVideoHash}` : ''}&autoplay=0&loop=0&title=0&byline=0&portrait=0`
    : null;

  // Parse content into paragraphs (simple markdown-like parsing)
  const contentSections = post.content.split('\n\n').map((paragraph, index) => {
    // Handle headers
    if (paragraph.startsWith('**') && paragraph.endsWith('**')) {
      const headerText = paragraph.slice(2, -2);
      return (
        <h3
          key={index}
          style={{
            color: '#c0c0c0',
            fontFamily: 'var(--font-display)',
            fontSize: '13px',
            fontWeight: 600,
            letterSpacing: '0.1em',
            textTransform: 'uppercase',
            marginTop: '32px',
            marginBottom: '12px'
          }}
        >
          {headerText}
        </h3>
      );
    }

    // Handle bullet lists
    if (paragraph.includes('\n- ')) {
      const lines = paragraph.split('\n');
      const header = lines[0];
      const items = lines.slice(1).filter(l => l.startsWith('- ')).map(l => l.slice(2));

      return (
        <div key={index}>
          {header.startsWith('**') && (
            <h3
              style={{
                color: '#c0c0c0',
                fontFamily: 'var(--font-display)',
                fontSize: '13px',
                fontWeight: 600,
                letterSpacing: '0.1em',
                textTransform: 'uppercase',
                marginTop: '32px',
                marginBottom: '12px'
              }}
            >
              {header.replace(/\*\*/g, '')}
            </h3>
          )}
          <ul style={{ margin: '12px 0', paddingLeft: '20px' }}>
            {items.map((item, i) => (
              <li
                key={i}
                style={{
                  color: '#8a8a8a',
                  fontFamily: 'var(--font-display)',
                  fontSize: '15px',
                  lineHeight: 1.7,
                  marginBottom: '8px'
                }}
              >
                {item.replace(/\*\*([^*]+)\*\*/g, '$1')}
              </li>
            ))}
          </ul>
        </div>
      );
    }

    // Regular paragraph
    return (
      <p
        key={index}
        style={{
          color: '#8a8a8a',
          fontFamily: 'var(--font-display)',
          fontSize: '15px',
          lineHeight: 1.7,
          marginBottom: '16px'
        }}
      >
        {paragraph}
      </p>
    );
  });

  return (
    <div className="min-h-screen" style={{ backgroundColor: '#141414' }}>
      <main
        className="mx-auto pb-32"
        style={{
          maxWidth: '800px',
          paddingTop: 'clamp(100px, 8vw + 60px, 180px)',
          paddingLeft: 'var(--side-padding)',
          paddingRight: 'var(--side-padding)'
        }}
      >
        {/* Back link - min-h-[44px] for touch-friendly tap target */}
        <Link
          href="/process"
          className="inline-flex items-center gap-2 mb-8 sm:mb-12 group min-h-[44px]"
          style={{
            color: '#5a5a5a',
            fontFamily: 'var(--font-display)',
            fontSize: '12px',
            fontWeight: 500,
            letterSpacing: '0.1em',
            textTransform: 'uppercase'
          }}
        >
          <svg
            width="16"
            height="16"
            viewBox="0 0 16 16"
            fill="none"
            stroke="currentColor"
            strokeWidth="1.5"
            style={{ transition: 'transform 200ms ease' }}
            className="group-hover:-translate-x-1"
          >
            <path d="M10 4L6 8L10 12" />
          </svg>
          Process
        </Link>

        {/* Category + Date */}
        <div className="flex items-center gap-4 mb-6">
          <span
            style={{
              color: '#4a4a4a',
              fontFamily: 'var(--font-display)',
              fontSize: '11px',
              fontWeight: 600,
              letterSpacing: '0.15em',
              textTransform: 'uppercase'
            }}
          >
            {post.category.replace('-', ' ')}
          </span>
          <span style={{ color: '#3a3a3a' }}>•</span>
          <span
            style={{
              color: '#4a4a4a',
              fontFamily: 'var(--font-display)',
              fontSize: '12px'
            }}
          >
            {new Date(post.date).toLocaleDateString('en-US', {
              year: 'numeric',
              month: 'long',
              day: 'numeric'
            })}
          </span>
        </div>

        {/* Title */}
        <h1
          style={{
            color: '#e8e8e8',
            fontFamily: 'var(--font-display)',
            fontWeight: 400,
            fontSize: 'clamp(28px, 4vw, 42px)',
            lineHeight: 1.2,
            letterSpacing: '0.01em',
            marginBottom: '24px'
          }}
        >
          {post.title}
        </h1>

        {/* Excerpt */}
        <p
          style={{
            color: '#7a7a7a',
            fontFamily: 'var(--font-display)',
            fontSize: '17px',
            lineHeight: 1.6,
            marginBottom: '40px'
          }}
        >
          {post.excerpt}
        </p>

        {/* Related Project Link - min-h-[44px] for touch target */}
        {relatedProject && (
          <Link
            href={`/projects/${relatedProject.slug}`}
            className="inline-flex items-center gap-3 mb-8 sm:mb-12 px-4 py-3 group min-h-[44px] flex-wrap"
            style={{
              backgroundColor: 'rgba(255, 255, 255, 0.03)',
              border: '1px solid rgba(255, 255, 255, 0.06)',
              borderRadius: '6px'
            }}
          >
            <span
              style={{
                color: '#5a5a5a',
                fontFamily: 'var(--font-display)',
                fontSize: '11px',
                fontWeight: 500,
                letterSpacing: '0.1em',
                textTransform: 'uppercase'
              }}
            >
              View Project
            </span>
            <span
              style={{
                color: '#a0a0a0',
                fontFamily: 'var(--font-display)',
                fontSize: '15px'
              }}
              className="group-hover:text-white transition-colors"
            >
              {relatedProject.title}
            </span>
            <svg
              width="14"
              height="14"
              viewBox="0 0 16 16"
              fill="none"
              stroke="currentColor"
              strokeWidth="1.5"
              style={{ color: '#5a5a5a', transition: 'transform 200ms ease' }}
              className="group-hover:translate-x-1"
            >
              <path d="M6 4L10 8L6 12" />
            </svg>
          </Link>
        )}

        {/* Breakdown Video */}
        {vimeoEmbedUrl && (
          <div className="mb-8 sm:mb-12">
            <p
              style={{
                color: '#5a5a5a',
                fontFamily: 'var(--font-display)',
                fontSize: '11px',
                fontWeight: 600,
                letterSpacing: '0.15em',
                textTransform: 'uppercase',
                marginBottom: '16px'
              }}
            >
              Breakdown
            </p>
            <div
              style={{
                position: 'relative',
                paddingBottom: '56.25%', // 16:9
                height: 0,
                overflow: 'hidden',
                borderRadius: '6px',
                backgroundColor: '#0a0a0a'
              }}
            >
              <iframe
                src={vimeoEmbedUrl}
                style={{
                  position: 'absolute',
                  top: 0,
                  left: 0,
                  width: '100%',
                  height: '100%',
                  border: 0
                }}
                allow="autoplay; fullscreen; picture-in-picture"
                allowFullScreen
                title="Breakdown video"
              />
            </div>
          </div>
        )}

        {/* Content */}
        <div className="mb-8 sm:mb-12">
          {contentSections}
        </div>

        {/* Tags */}
        {post.tags && post.tags.length > 0 && (
          <div className="flex flex-wrap gap-2 pt-8 border-t" style={{ borderColor: 'rgba(255, 255, 255, 0.06)' }}>
            {post.tags.map((tag) => (
              <span
                key={tag}
                style={{
                  color: '#4a4a4a',
                  fontFamily: 'var(--font-display)',
                  fontSize: '11px',
                  fontWeight: 500,
                  letterSpacing: '0.05em',
                  padding: '4px 10px',
                  backgroundColor: 'rgba(255, 255, 255, 0.03)',
                  borderRadius: '4px'
                }}
              >
                {tag}
              </span>
            ))}
          </div>
        )}
      </main>
    </div>
