        }

        /* ============================================
           RESPONSIVE COLUMN COUNT (~15% larger images)
           Columns still need discrete breakpoints
           but all spacing is now fluid
           ============================================ */

        @media (max-width: 1600px) {
          .photo-grid {
            column-count: 5 !important;
          }
        }

        @media (max-width: 1200px) {
          .photo-grid {
            column-count: 4 !important;
          }
