        @media (max-width: 1024px) {
          .photo-grid {
            column-count: 3 !important;
          }
        }

        @media (max-width: 768px) {
          .photo-grid {
            column-count: 2 !important;
          }
        }

        @media (max-width: 480px) {
          .photo-grid {
            column-count: 2 !important;
          }
        }
      `}</style>
    </main>
